        end else begin
            e0q_v <= (PIPE != 0) && e0_go;
            e0r_v <= e0q_v;
            e1_v <= (PIPE != 0) ? e0r_v : e0_go;
            if (st != S_EMIT) begin
                ej <= 3'd0; ek <= 4'd0; emit_done_r <= 1'b0;
            end else if (e0_go) begin
                if (ek == 4'd7) begin
                    ek <= 4'd0;
                    if (ej == CPR[2:0] - 1'b1) emit_done_r <= 1'b1;
                    ej <= ej + 1'b1;
                end else ek <= ek + 1'b1;
            end
        end
    end
    // E0 -> SRAM read -> E1 (PIPE 1 only; checked at elaboration).  q_* / rq_* on clk_ctl at e+1, r_* and the macro
    // read on clk_rd at e+2, E1 on clk_rd at e+3 (= e1_vn, two cycles after E0q).
    reg [1:0]  q_off, r_off;
    reg [2:0]  q_j, q_k, r_j, r_k;
    reg [SLW-1:0] q_s, r_s;
    wire [3:0] ek1 = ek + 4'd1;
    // n32: E0q captures every cycle (r_* / E1 / the macros use it only on the e0_go -> rq_v -> e1_vn edges)
    always @(posedge clk_ctl) begin
        // ej advances to CPR after the final row. Define the inactive read, too:
        // downstream valid is off there; this also preserves a fully defined LEC cone.
        q_off <= (ej < CPR) ? roff[ej] : 2'b00; q_j <= ej; q_k <= ek[2:0]; q_s <= slot;
        rq_ea <= {ej, ek[0] ? ek1[3:1] : ek[3:1]};
        rq_oa <= {ej, ek[3:1]};
        rq_aa <= ej;
    end
    wire [3:0] q_k0;                          // 4 kept copies of q_k[0] (16 r_k0 copies each)
    wire [1:0] r_offc [0:1];                  // 2 kept copies of r_off (22 e1_off copies each)
    generate
        for (gi = 0; gi < 4; gi = gi + 1) begin : g_qk0
            (* keep = 1 *) ot_s81eng_kq #(.W(1)) u_q (.clk(clk_ctl), .d(ek[0]), .q(q_k0[gi]));
        end
        for (gi = 0; gi < 2; gi = gi + 1) begin : g_roff
            (* keep = 1 *) ot_s81eng_kq #(.W(2)) u_r (.clk(clk_rd), .d(q_off), .q(r_offc[gi]));
        end
    endgenerate
    always @(posedge clk_ctl or negedge rrst[3])
        if (!rrst[3]) rq_v <= 1'b0;
        else        rq_v <= e0_go;
    always @(posedge clk_rd) begin
        r_off <= q_off; r_j <= q_j; r_k <= q_k; r_s <= q_s;
    end
    // n32: E1 captures every cycle (E2 samples it only on the e1_v edge, = the e1_vn capture edge + 1).
    wire [63:0] r_k0;                        // 64 kept copies of r_k[0]: copy i muxes lo (i < 32) / hi bits [8(i%32) +: 8]
    wire [1:0]  e1_offc [0:43];              // 44 kept copies of e1_off: 0..31 e2_d slices, 32..43 e1_a8s[95:0] slices
    wire [2:0]  e1_kc [0:3];                 // 4 kept copies of e1_k: scale bits [2i +: 2]
    generate
        for (gi = 0; gi < 64; gi = gi + 1) begin : g_rk0
            (* keep = 1 *) ot_s81eng_kq #(.W(1)) u_k (.clk(clk_rd), .d(q_k0[gi / 16]), .q(r_k0[gi]));
        end
        for (gi = 0; gi < 32; gi = gi + 1) begin : g_e1m
            always @(posedge clk_rd) begin
`ifdef OT_ENGRAM_MUT_RA512_PAR
                e1_lo[8*gi +: 8] <= rd_e[8*gi +: 8];          // NEGATIVE CONTROL ONLY: ignores the odd-ek macro swap
`else
                e1_lo[8*gi +: 8] <= r_k0[gi] ? rd_o[8*gi +: 8] : rd_e[8*gi +: 8];
`endif
                e1_hi[8*gi +: 8] <= r_k0[32 + gi] ? rd_e[8*gi +: 8] : rd_o[8*gi +: 8];
            end
        end
        for (gi = 0; gi < 44; gi = gi + 1) begin : g_e1o
            (* keep = 1 *) ot_s81eng_kq #(.W(2)) u_o (.clk(clk_rd), .d(r_offc[gi / 22]), .q(e1_offc[gi]));
        end
        for (gi = 0; gi < 4; gi = gi + 1) begin : g_e1k
            (* keep = 1 *) ot_s81eng_kq #(.W(3)) u_k (.clk(clk_rd), .d(r_k), .q(e1_kc[gi]));
        end
    endgenerate
    always @(posedge clk_rd) begin
        e1_a8 <= rd_a;
        e1_off <= r_off; e1_j <= r_j; e1_k <= r_k; e1_s <= r_s;
    end
    // E2: byte shift
    reg [255:0] e2_d;
    reg [7:0]   e2_scale;                   // this beat's block exponent (row byte 256 + k)
    reg [63:0]  e2_sc8;                     // all 8 block exponents (row bytes 256..263, byte 256 at [7:0]) for the CRC
    reg [31:0]  e2_crc;
    reg [2:0]   e2_j, e2_k;
    wire [511:0] e1_cat = {e1_hi, e1_lo};
    always @(posedge clk_em or negedge rrst[3]) begin
        if (!rrst[3]) e2_v <= 1'b0;
        else e2_v <= e1_v;
    end
    // n32: the byte shifts as explicit 4:1 selects per 8-bit slice, each slice on its own kept e1_off copy; the E2
    // enable e1_v as 24 kept copies (ev[0..15] e2_d 16-bit slices, ev[16..19] e2_sc8, ev[20..21] e2_crc, ev[22] scale
    // + j, ev[23] k + s); same value as e1_cat[{e1_off,6'd0} +: 256] / e1_a8s.
    wire [255:0] sh_d;
    wire [95:0]  sh_a;
    wire [23:0]  ev;
    reg  [7:0]   sc_m;
    generate
        for (gi = 0; gi < 32; gi = gi + 1) begin : g_shd
            wire [1:0] o = e1_offc[gi];
            assign sh_d[8*gi +: 8] = ({8{o == 2'd0}} & e1_cat[8*gi +: 8])       | ({8{o == 2'd1}} & e1_cat[64 + 8*gi +: 8])
                                   | ({8{o == 2'd2}} & e1_cat[128 + 8*gi +: 8]) | ({8{o == 2'd3}} & e1_cat[192 + 8*gi +: 8]);
        end
        for (gi = 0; gi < 12; gi = gi + 1) begin : g_sha
            wire [1:0] o = e1_offc[32 + gi];
            wire [255:0] a8w = e1_a8;
            assign sh_a[8*gi +: 8] = ({8{o == 2'd0}} & a8w[8*gi +: 8])
                                   | ({8{o == 2'd1}} & a8w[64 + 8*gi +: 8])
                                   | ({8{o == 2'd2}} & a8w[128 + 8*gi +: 8])
                                   | ({8{o == 2'd3}} & ((gi < 8) ? a8w[(192 + 8*gi) % 256 +: 8] : 8'd0));   // >> 192: bytes >= 64 are 0
        end
        for (gi = 0; gi < 24; gi = gi + 1) begin : g_ev
            (* keep = 1 *) ot_s81eng_kqr #(.W(1)) u_v (.clk(clk_ctl), .rst_n(rrst[7]), .d(e0r_v), .q(ev[gi]));
        end
        for (gi = 0; gi < 16; gi = gi + 1) begin : g_e2d
            always @(posedge clk_em) if (ev[gi]) e2_d[16*gi +: 16] <= sh_d[16*gi +: 16];
        end
        for (gi = 0; gi < 4; gi = gi + 1) begin : g_e2s
            always @(posedge clk_em) if (ev[16 + gi]) e2_sc8[16*gi +: 16] <= sh_a[16*gi +: 16];
        end
        for (gi = 0; gi < 2; gi = gi + 1) begin : g_e2c
            always @(posedge clk_em) if (ev[20 + gi]) e2_crc[16*gi +: 16] <= sh_a[64 + 16*gi +: 16];   // byte 264 = crc[7:0]
        end
    endgenerate
    integer ib;
    always @(*) begin
        sc_m = 8'd0;
`ifdef OT_ENGRAM_MUT_ONESCALE
        sc_m = sh_a[7:0];                   // NEGATIVE CONTROL ONLY: the pre-F13 one-exponent decode (block 0's on every beat)
`else
        for (ib = 0; ib < 8; ib = ib + 1) sc_m[ib] = sh_a[8 * e1_kc[ib / 2] + ib];
`endif
    end
    always @(posedge clk_em) if (ev[22]) begin e2_scale <= sc_m; e2_j <= e1_j; end
    always @(posedge clk_em) if (ev[23]) begin e2_k <= e1_k; e2_s <= e1_s; end

    // Fixed two-stage registered output transport. There is no FIFO
    // occupancy or readiness term capable of moving a compiler output slot.
    localparam integer FW = 5 + 3 + SLW + 264;
    reg transport_v, ov;
    reg [FW-1:0] transport_d, od;
    wire [4:0] e2_col = crank * CPR + e2_j;
    always @(posedge clk_em or negedge rrst[8]) begin
        if(!rrst[8]) begin transport_v<=0;ov<=0;end
        else begin transport_v<=e2_v;ov<=transport_v;end
    end
    always @(posedge clk_em) begin
        transport_d<={e2_col,e2_k,e2_s,e2_scale,e2_d};
        od<=transport_d;
    end
    assign o_valid=ov;
    assign {o_col,o_beat,o_slot,o_data}=od;

    // ---- CRC-32/MPEG-2 over the 256 codes and the 8 exponent bytes ----------------------
    function automatic [31:0] crc_byte(input [31:0] c, input [7:0] b);
        integer i;
        reg [31:0] x;
        begin
            x = c;
            for (i = 7; i >= 0; i = i - 1)
                x = {x[30:0], 1'b0} ^ ((x[31] ^ b[i]) ? POLY : 32'd0);
            crc_byte = x;
        end
    endfunction
    function automatic [31:0] crc_sc8(input [31:0] c, input [63:0] s);   // the 8 exponent bytes, byte 256 first
        integer i;
        reg [31:0] x;
        begin
            x = c;
            for (i = 0; i < 8; i = i + 1) x = crc_byte(x, s[8*i +: 8]);
            crc_sc8 = x;
        end
    endfunction
    function automatic [31:0] crc_beat(input [31:0] c, input [255:0] d);
        integer i;
        reg [31:0] x;
        begin
            x = c;
            for (i = 0; i < 32; i = i + 1) x = crc_byte(x, d[8*i +: 8]);
            crc_beat = x;
        end
    endfunction
    // ---- CRCMAT: constant GF(2) columns and the per-output-bit masks ------------------------
    wire [31:0] m_dcol [0:255];              // crc_beat(0, e_i)
    wire [31:0] m_scol [0:31];               // crc_beat(e_k, 0)
    wire [31:0] m_bcol [0:63];               // crc_sc8(0, e_i)
    wire [31:0] m_fcol [0:31];               // crc_sc8(e_k, 0)
    wire [255:0] m_dmask [0:31];
    wire [31:0]  m_smask [0:31], m_fmask [0:31];
    wire [63:0]  m_bmask [0:31];
    genvar gmi, gmj;
    generate
        for (gmi = 0; gmi < 256; gmi = gmi + 1) begin : g_mdc
            localparam [31:0] C = crc_beat(32'd0, 256'd1 << gmi);
            assign m_dcol[gmi] = C;
        end
        for (gmi = 0; gmi < 32; gmi = gmi + 1) begin : g_msc
            localparam [31:0] C = crc_beat(32'd1 << gmi, 256'd0);
            localparam [31:0] F = crc_sc8(32'd1 << gmi, 64'd0);
            assign m_scol[gmi] = C; assign m_fcol[gmi] = F;
        end
        for (gmi = 0; gmi < 64; gmi = gmi + 1) begin : g_mbc
            localparam [31:0] C = crc_sc8(32'd0, 64'd1 << gmi);
            assign m_bcol[gmi] = C;
        end
        for (gmj = 0; gmj < 32; gmj = gmj + 1) begin : g_mm
            for (gmi = 0; gmi < 256; gmi = gmi + 1) begin : g_d
                assign m_dmask[gmj][gmi] = m_dcol[gmi][gmj];
            end
            for (gmi = 0; gmi < 32; gmi = gmi + 1) begin : g_s
                assign m_smask[gmj][gmi] = m_scol[gmi][gmj];
                assign m_fmask[gmj][gmi] = m_fcol[gmi][gmj];
            end
            for (gmi = 0; gmi < 64; gmi = gmi + 1) begin : g_b
                assign m_bmask[gmj][gmi] = m_bcol[gmi][gmj];
            end
        end
    endgenerate
    reg [31:0] crc;
    reg        e3_last;
    wire [31:0] mx_d, mx_s, mx_f;            // crc_beat(0, e2_d), crc_beat(crc, 0), crc_sc8(crc, e3_sc8)
    reg  [63:0] e3_sc8;
    generate
        for (gmj = 0; gmj < 32; gmj = gmj + 1) begin : g_mx
            assign mx_d[gmj] = ^(e2_d & m_dmask[gmj]);
            assign mx_s[gmj] = ^(crc & m_smask[gmj]);
            assign mx_f[gmj] = (^(crc & m_fmask[gmj])) ^ (^(e3_sc8 & m_bmask[gmj]));
        end
    endgenerate
    wire [31:0] beat_d = (CRCMAT != 0) ? mx_d : crc_beat(32'd0, e2_d);
    wire [31:0] beat_s = (CRCMAT != 0) ? mx_s : crc_beat(crc, 256'd0);
    wire [31:0] fold   = (CRCMAT != 0) ? mx_f : crc_sc8(crc, e3_sc8);
    reg [31:0] e3_exp;
    generate
        if (PIPE == 0) begin : g_crc0
            always @(posedge clk_em or negedge rrst[14]) begin
                if (!rrst[14]) begin
                    crc <= 32'hFFFFFFFF; e3_last <= 1'b0;
                end else begin
                    e3_last <= e2_v && e2_k == 3'd7;
                    if (e2_v) crc <= (CRCMAT != 0) ? (((e2_k == 3'd0) ? crc_beat(32'hFFFFFFFF, 256'd0) : beat_s) ^ beat_d)
                                                   : crc_beat((e2_k == 3'd0) ? 32'hFFFFFFFF : crc, e2_d);
                end
            end
            always @(posedge clk_em) if (e2_v && e2_k == 3'd7) begin e3_sc8 <= e2_sc8; e3_exp <= e2_crc; e3_s <= e2_s; end
        end else begin : g_crc1
            // stage a: data term; stage b: state term ^ data term
            reg [31:0] ga;
            reg        a_v, a_last;
            reg [63:0] a_sc8;
            reg [31:0] a_exp;
            reg [SLW-1:0] a_s;
            // n32: crc enable / first-beat select as 4 kept copies each (8 crc bits per copy); ga / a_* / e3_* capture
            // every cycle (consumed only on the a_v / a_last / e3_last edge that follows their e2_v / a_last capture).
            wire [3:0] avc, afc;
            for (gi = 0; gi < 4; gi = gi + 1) begin : g_cc
                (* keep = 1 *) ot_s81eng_kqr #(.W(1)) u_v (.clk(clk_em), .rst_n(rrst[11]), .d(e2_v), .q(avc[gi]));
                (* keep = 1 *) ot_s81eng_kq  #(.W(1)) u_f (.clk(clk_em), .d(e2_k == 3'd0), .q(afc[gi]));
            end
            wire [31:0] c_first = (CRCMAT != 0) ? crc_beat(32'hFFFFFFFF, 256'd0) : 32'd0;
            wire [31:0] c_nxt_f = (CRCMAT != 0) ? (c_first ^ ga) : (crc_beat(32'hFFFFFFFF, 256'd0) ^ ga);
            wire [31:0] c_nxt_s = (CRCMAT != 0) ? (beat_s ^ ga)  : (crc_beat(crc, 256'd0) ^ ga);
            always @(posedge clk_em or negedge rrst[11]) begin
                if (!rrst[11]) begin a_v <= 1'b0; a_last <= 1'b0; e3_last <= 1'b0; end
                else begin
                    a_v <= e2_v;
                    a_last <= e2_v && e2_k == 3'd7;
                    e3_last <= a_last;
                end
            end
            for (gi = 0; gi < 4; gi = gi + 1) begin : g_crc
                always @(posedge clk_em or negedge rrst[9+gi/2])
                    if (!rrst[9+gi/2]) crc[8*gi +: 8] <= 8'hFF;
                    else if (avc[gi]) crc[8*gi +: 8] <= afc[gi] ? c_nxt_f[8*gi +: 8] : c_nxt_s[8*gi +: 8];
            end
            always @(posedge clk_em) begin
                ga <= beat_d;
                a_sc8 <= e2_sc8; a_exp <= e2_crc; a_s <= e2_s;
            end
            always @(posedge clk_em) begin e3_sc8 <= a_sc8; e3_exp <= a_exp; e3_s <= a_s; end
        end
    endgenerate
    // final: fold the 8 exponent bytes and compare
    always @(posedge clk_em or negedge rrst[12]) begin
        if (!rrst[12]) begin
            st_valid <= 1'b0; st_slot <= {SLW{1'b0}}; st_bad <= 1'b0; fault <= 1'b0;
        end else begin
            if (protocol_bad) fault <= 1;
            st_valid <= e3_last;
            if (e3_last) begin
                st_slot <= e3_s;
                st_bad <= (fold != e3_exp) || protocol_bad;
                if (fold != e3_exp) fault <= 1'b1;
            end
        end
    end
endmodule

module dsfd_engram_lkp_ra640_hx #(
    parameter integer ROWSTRIPE  = 0,
    parameter integer NSLOT      = 8,
    parameter integer SLW        = 3,
    parameter integer RETURN_AGE = 640
) (
    input  wire                  ck,
    input  wire                  ck_seed,
    input  wire [5:0]            ck_hash,
    input  wire                  ck_n,      // st9: N-face pin flops (window in, row beats/status out)
    input  wire                  ck_s,      // st9: S-face pin flops (HBM request out, HBM response in); st10: + engine control
    input  wire                  ck_rd,     // st10: read-select region (c* bank captures, E1)
    input  wire                  rst_n,
`ifdef OT_S81ENG_RR_N32
    input wire[15:0] rst_regions, // same external release phase, actual per-control owners
`endif
    input  wire                  cfg_layer,
    input  wire [1:0]            cfg_rank,
    output wire [67:0]           hx_w,
    input  wire [1151:0]         hx_res,
    // window (compiler slot)
    input  wire                  win_v,
    input  wire [SLW-1:0]        win_slot,
    input  wire [4*ENG_ID_W-1:0] win_ids,
    // HBM request (fixed slot, no ready)
    output reg                   hq_v,
    output reg  [30:0]           hq_atom,
    output reg  [2:0]            hq_tag,
    // HBM response (push, slot-tagged)
    input  wire                  hr_v,
    input  wire [SLW-1:0]        hr_slot,
    input  wire [2:0]            hr_tag,
    input  wire [3:0]            hr_idx,
    input  wire [255:0]          hr_d,
    // row beats (fixed slots)
    output reg                   o_v,
    output reg  [4:0]            o_col,
    output reg  [2:0]            o_beat,
    output reg  [SLW-1:0]        o_slot,
    output reg  [263:0]          o_d,
    // row status
    output reg                   st_v,
    output reg  [SLW-1:0]        st_slot,
    output reg                   st_bad,
    output reg                   fault
);
    // ---- input pin flops ------------------------------------------------------------
    reg                  wv_q, hrv_q, cl_q;
    reg [1:0]            cr_q;
    reg [SLW-1:0]        ws_q, hrs_q;
    reg [4*ENG_ID_W-1:0] wid_q;
    reg [2:0]            hrt_q;
    reg [3:0]            hri_q;
    reg [255:0]          hrd_q;
    // st9 (coordinator 10-17 ~09:35): regional face roots for the pin flops.  ck_n / ck_s / ck are phase-0 1:1
    // roots of one PLL (same edge), so every pin flop still captures on the same cycle: 0 cycles added.
    always @(posedge ck_n or negedge rst_n)
        if (!rst_n) wv_q <= 1'b0;
        else        wv_q <= win_v;
    always @(posedge ck_s or negedge rst_n)
        if (!rst_n) hrv_q <= 1'b0;
        else        hrv_q <= hr_v;
    always @(posedge ck_n) begin ws_q <= win_slot; wid_q <= win_ids; end
    always @(posedge ck_s) begin hrs_q <= hr_slot; hrt_q <= hr_tag; hri_q <= hr_idx; hrd_q <= hr_d; end
    always @(posedge ck) begin cl_q <= cfg_layer; cr_q <= cfg_rank; end
    wire [2:0] hrt_w;                        // ra640: kept second pin flop of hr_tag (seen write decode / wbank)
    (* keep = 1 *) ot_s81eng_kq #(.W(3)) u_hrt_w (.clk(ck_s), .d(hr_tag), .q(hrt_w));
    // ELEM-ENG2 n32 (native census 10-21: wv_q 115 / hri_q 40 loads): kept pin-flop copies, same pins / edges / reset.
    // wv_c[4:0] -> accept_ids groups, wv_c[7:5] -> accept_seen bank pairs; hri_w[4b +: 4] -> accept_seen bank b.
    wire [7:0]  wv_c;
    wire [23:0] hri_w;
    genvar gc;
    generate
        for (gc = 0; gc < 8; gc = gc + 1) begin : g_wv_c
            (* keep = 1 *) ot_s81eng_kqr #(.W(1)) u_wv (.clk(ck_n), .rst_n(rst_n), .d(win_v), .q(wv_c[gc]));
        end
        for (gc = 0; gc < 6; gc = gc + 1) begin : g_hri_w
            (* keep = 1 *) ot_s81eng_kq #(.W(4)) u_hri (.clk(ck_s), .d(hr_idx), .q(hri_w[4*gc +: 4]));
        end
    endgenerate
    // ---- engine ---------------------------------------------------------------------
    wire        e_hqv, e_ov, e_stv, e_stb, e_fault;
    wire [30:0] e_hqa;
    wire [2:0]  e_hqt;
    wire [4:0]  e_oc;
    wire [2:0]  e_ob;
    wire [SLW-1:0] e_os, e_sts;
    wire [263:0] e_od;
    ot_s81_engram_lookup_ra640_hx #(.RETURN_AGE(RETURN_AGE), .ROWSTRIPE(ROWSTRIPE), .NR(4), .CPR(6), .NSLOT(NSLOT), .ABW(36),
                                  .PIPE(1)) u_e (
        .clk(ck), .clk_ctl(ck_s), .clk_rd(ck_rd), .clk_em(ck_n), .clk_seed(ck_seed), .clk_hash(ck_hash), .rst_n(rst_n),
`ifdef OT_S81ENG_RR_N32
        .rst_regions(rst_regions),
`endif
        .cfg_layer(cl_q), .cfg_rank(cr_q), .hx_w(hx_w), .hx_res(hx_res),
        .win_valid(wv_q), .win_slot(ws_q), .win_ids(wid_q),
        .hq_valid(e_hqv), .hq_atom(e_hqa), .hq_len(), .hq_tag(e_hqt),
        .hr_valid(hrv_q), .hr_slot(hrs_q), .hr_tag(hrt_q), .hr_tag_w(hrt_w), .hr_idx(hri_q), .win_valid_c(wv_c), .hr_idx_w(hri_w), .hr_data(hrd_q),
        .o_valid(e_ov), .o_col(e_oc), .o_beat(e_ob), .o_slot(e_os), .o_data(e_od),
        .st_valid(e_stv), .st_slot(e_sts), .st_bad(e_stb), .fault(e_fault));
    // ---- output pin flops -----------------------------------------------------------
    always @(posedge ck_s or negedge rst_n)
        if (!rst_n) hq_v <= 1'b0;
        else        hq_v <= e_hqv;
    always @(posedge ck_n or negedge rst_n)
        if (!rst_n) begin o_v <= 1'b0; st_v <= 1'b0; end
        else begin o_v <= e_ov; st_v <= e_stv; end
    always @(posedge ck or negedge rst_n)
        if (!rst_n) fault <= 1'b0;
        else        fault <= e_fault;
    always @(posedge ck_s) begin hq_atom <= e_hqa; hq_tag <= e_hqt; end
    always @(posedge ck_n) begin
        o_col <= e_oc; o_beat <= e_ob; o_slot <= e_os; o_d <= e_od;
        st_slot <= e_sts; st_bad <= e_stb;
    end
endmodule
